import re
with open('/workdir/data/dict.txt') as f:
    words = [line.strip() for line in f if line.strip()]
valid = []
for w in words:
    if re.match(r'^[a-z]+$', w):
        if len(w) >= 4:
            valid.append(w)
print(f'Total valid words: {len(valid)}')
print(f'Sample: {valid[:20]}')
